import{_ as l,C as o,c as i,o as d,a3 as n,G as s,j as e,a as r}from"./chunks/framework.Dokpd4od.js";const v=JSON.parse('{"title":"Vendor bills","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/orders/vendor-bills.md","filePath":"master/supply-chain/purchase/orders/vendor-bills.md","lastUpdated":1791902625000}'),h={name:"master/supply-chain/purchase/orders/vendor-bills.md"};function c(u,t,b,g,p,m){const a=o("ImagePopup");return d(),i("div",null,[t[0]||(t[0]=n('<h1 id="vendor-bills" tabindex="-1">Vendor bills <a class="header-anchor" href="#vendor-bills" aria-label="Permalink to &quot;Vendor bills&quot;">​</a></h1><p>A vendor bill is the invoice a supplier sends you after delivery. In Purchase you do not type it in again. You click <strong>Create Bill</strong> on the order and Aureus builds the bill from what you received. This keeps your books in line with your stock.</p><blockquote><p><strong>In simple words:</strong> Receive the goods first. Then click <strong>Create Bill</strong> and Aureus bills only what has arrived and is not yet billed.</p></blockquote><p>Open the order at <code>Purchase → Orders → Purchase Orders</code>, then click <strong>Create Bill</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Bills are Finance documents. They need the Invoices or Accounting app and a purchase journal. Receipts need the Inventory app. Without Inventory, no receipts are made, so the order has nothing to bill from receipts.</p></div><h2 id="when-the-create-bill-button-shows" tabindex="-1">When the Create Bill button shows <a class="header-anchor" href="#when-the-create-bill-button-shows" aria-label="Permalink to &quot;When the Create Bill button shows&quot;">​</a></h2><p>The button is on the order header in these states:</p><table tabindex="0"><thead><tr><th>Order state</th><th>Create Bill</th></tr></thead><tbody><tr><td>RFQ, RFQ Sent, To Approve</td><td>Hidden</td></tr><tr><td>Purchase Order</td><td>Shown</td></tr><tr><td>Locked</td><td>Shown</td></tr><tr><td>Canceled</td><td>Hidden</td></tr></tbody></table><p>The button is grey when there is nothing to bill and blue when there is.</p><h2 id="create-a-bill-from-po-3" tabindex="-1">Create a bill from PO/3 <a class="header-anchor" href="#create-a-bill-from-po-3" aria-label="Permalink to &quot;Create a bill from PO/3&quot;">​</a></h2><p>Order <strong>PO/3</strong> from Consolidated Components has two lines: 15 <strong>SSD 512GB</strong> and 10 <strong>Laptop Battery</strong>. You validated the receipt <strong>WH/IN/11</strong>, so both lines show a <strong>Received</strong> quantity.</p><ol><li>Open <code>Purchase → Orders → Purchase Orders</code> and click <strong>PO/3</strong>.</li><li>Check the <strong>Received</strong> and <strong>Billed</strong> columns on the <strong>Products</strong> tab. <strong>Billed</strong> is still 0.</li></ol>',12)),s(a,{src:"/images1/purchase/bill_po_lines.png",alt:"PO/3 products tab with Received 15 and 10 and Billed 0 on both lines"}),t[1]||(t[1]=e("ol",{start:"3"},[e("li",null,[r("Click "),e("strong",null,"Create Bill"),r(" in the header.")])],-1)),s(a,{src:"/images1/purchase/bill_create_button.png",alt:"Purchase order PO/3 header with the Create Bill button highlighted"}),t[2]||(t[2]=e("ol",{start:"4"},[e("li",null,[r("Read the message "),e("strong",null,"Bill created"),r(". The bill is a draft in Finance.")]),e("li",null,[r("Click "),e("strong",null,"Vendor Bills"),r(" in the switcher at the top of the order. The new bill is listed.")])],-1)),s(a,{src:"/images1/purchase/bill_tab.png",alt:"Manage PO/3 Bills sub page listing the new draft bill with its totals"}),t[3]||(t[3]=e("ol",{start:"6"},[e("li",null,[r("Click the bill to open it. Check the lines, then click "),e("strong",null,"Confirm"),r(" in Finance.")])],-1)),s(a,{src:"/images1/purchase/bill_open_draft.png",alt:"Draft vendor bill created from PO/3 with SSD 512GB and Laptop Battery lines"}),t[4]||(t[4]=n(`<h2 id="how-the-quantity-is-chosen" tabindex="-1">How the quantity is chosen <a class="header-anchor" href="#how-the-quantity-is-chosen" aria-label="Permalink to &quot;How the quantity is chosen&quot;">​</a></h2><p>For each line, Aureus bills <strong>received quantity minus billed quantity</strong>. Partly delivered orders therefore get a bill for the delivered part only.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Received 15  -  Billed 0   =  bill 15</span></span>
<span class="line"><span>Later, received 5 more, so received 20  -  billed 15  =  bill 5</span></span></code></pre></div><p>The bill copies the price, discount and taxes of each order line. It uses the order&#39;s vendor, currency and payment term.</p><p>If the total to bill is below zero, for example after a return, Aureus makes a vendor refund instead of a bill.</p><h2 id="messages-you-may-see" tabindex="-1">Messages you may see <a class="header-anchor" href="#messages-you-may-see" aria-label="Permalink to &quot;Messages you may see&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td><strong>Bill created</strong></td><td>The bill was made.</td><td>Open it from the <strong>Vendor Bills</strong> tab.</td></tr><tr><td><strong>No invoiceable lines</strong></td><td>Nothing is received, or everything is already billed.</td><td>Validate the receipt first. See <a href="./../../inventories/operations/receipts.html">Receipts</a>.</td></tr><tr><td><strong>Accounting is not set up</strong></td><td>No purchase journal is available.</td><td>Set up Accounting, then try again.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Click <strong>Create Bill</strong> again after each new delivery. Each click bills only what is new.</p></div><h2 id="the-bills-tab" tabindex="-1">The Bills tab <a class="header-anchor" href="#the-bills-tab" aria-label="Permalink to &quot;The Bills tab&quot;">​</a></h2><p>Open the order and click <strong>Vendor Bills</strong>. The page is named <strong>Manage PO/3 Bills</strong>. The badge on the tab shows how many bills exist.</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Number</strong></td><td>The bill number</td></tr><tr><td><strong>State</strong></td><td>Draft, Posted or Canceled</td></tr><tr><td><strong>Customer</strong></td><td>The vendor on the bill</td></tr><tr><td><strong>Bill Date</strong></td><td>The date on the bill</td></tr><tr><td><strong>Due Date</strong></td><td>The date payment is due</td></tr><tr><td><strong>Tax Excluded</strong></td><td>Amount before tax</td></tr><tr><td><strong>Tax</strong></td><td>Tax amount</td></tr><tr><td><strong>Total</strong></td><td>Amount including tax</td></tr><tr><td><strong>Amount Due</strong></td><td>What is still unpaid</td></tr><tr><td><strong>Payment State</strong></td><td>Paid, partly paid or not paid</td></tr></tbody></table><h2 id="billing-status" tabindex="-1">Billing status <a class="header-anchor" href="#billing-status" aria-label="Permalink to &quot;Billing status&quot;">​</a></h2><p>Every order has a billing status. It tells you where billing stands.</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Nothing to bill</td><td>Nothing is received yet, or the order is not confirmed.</td></tr><tr><td><strong>Waiting Bills</strong></td><td>Some received goods have no bill yet.</td></tr><tr><td><strong>Fully Billed</strong></td><td>Everything received is billed.</td></tr></tbody></table><p>The status updates after each receipt and each bill. On the order list, the <strong>Waiting Bills</strong> and <strong>Bills Received</strong> tabs help you find orders to chase.</p><h2 id="cancel-rules" tabindex="-1">Cancel rules <a class="header-anchor" href="#cancel-rules" aria-label="Permalink to &quot;Cancel rules&quot;">​</a></h2><p>You cannot cancel an order that still has bills which are not canceled. The message is <strong>The order cannot be canceled. You must first cancel their related vendor bills.</strong> Cancel the bills in Finance, then cancel the order.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p><strong>Create Bill</strong> adds a vendor bill in Finance. The bill is linked to the order, and its origin shows the order name, such as <strong>PO/3</strong>. The order&#39;s <strong>Billed</strong> column grows when the bill is posted. Paying the bill is done in Finance.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./purchase-orders.html">Purchase orders</a></li><li><a href="./../../inventories/operations/receipts.html">Receipts</a></li><li><a href="./../../../finance/vendor-bills/">Vendor bills overview in Finance</a></li><li><a href="./../../../finance/vendor-bills/create-bill.html">Create a vendor bill in Finance</a></li></ul>`,21))])}const f=l(h,[["render",c]]);export{v as __pageData,f as default};
